const items=[...document.querySelectorAll('.process li')];const toggle=document.getElementById('demo-toggle');let current=0;let timer;function start(){timer=setInterval(()=>{items[current].classList.remove('active');current=(current+1)%items.length;items[current].classList.add('active')},2200)}if(!matchMedia('(prefers-reduced-motion: reduce)').matches)start();else toggle.textContent='Play demo';toggle.addEventListener('click',()=>{if(timer){clearInterval(timer);timer=null;toggle.textContent='Play demo'}else{start();toggle.textContent='Pause demo'}});document.getElementById('year').textContent=new Date().getFullYear();
